import{_ as c,o,c as d,a3 as i}from"./chunks/framework.DAK02U1-.js";const h=JSON.parse('{"title":"封闭性","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"封闭性 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/hermeticity"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/hermeticity"}]]},"headers":[],"relativePath":"zh/xclang/design/hermeticity.md","filePath":"zh/xclang/design/hermeticity.md","lastUpdated":1794509097000}'),t={name:"zh/xclang/design/hermeticity.md"};function l(a,e,n,r,s,b){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="封闭性" tabindex="-1">封闭性 <a class="header-anchor" href="#封闭性" aria-label="Permalink to &quot;封闭性&quot;">​</a></h1><p>xclang 对所有目标平台遵循同一条原则：</p><blockquote><p>编译出的程序在运行时只依赖目标操作系统必定自带且不允许二次分发的系统库，其余所有依赖均静态链接进二进制文件中；在构建时，来自工具链外部的唯一输入是厂商 SDK。</p></blockquote><p>所有内置目标平台以及<a href="./roadmap#targets">路线图</a>上的每个目标平台均遵循这一原则。编译出的二进制文件作为单个文件即可在满足目标操作系统最低版本要求的任意机器上直接运行，无需安装 C++ 运行时软件包，也无需随附运行时 DLL。</p><p>在构建时，来自工具链外部的唯一输入是不允许二次分发的厂商 SDK（<a href="./../guide/cross-compiling#vendor-sdks">厂商 SDK</a>）：</p><ul><li><strong>macOS 目标平台</strong>：在 macOS 主机上，<code>clang</code> 基于本机 Xcode 或 Command Line Tools 的 SDK（<code>xcrun</code>）构建，xclang 不锁定它的版本。在 Linux 与 Windows 主机上，<code>xclang sdk fetch macos</code> 会下载按版本、<code>sha256</code> 与内容摘要双重锁定的 Apple SDK（<a href="./macos#apple-s-sdk-without-xcode">macOS</a>）。</li><li><strong>Windows MSVC 目标平台</strong>：<code>xclang sdk fetch windows</code> 会下载按版本与 <code>sha256</code> 锁定的微软 CRT、STL 与 Windows SDK（<a href="./windows#the-sdk-without-visual-studio">Windows</a>）。在未下载 SDK 的 Windows 主机上，<code>clang</code> 会回退使用本机安装的 Visual Studio，xclang 不锁定其版本。</li></ul><h2 id="程序在运行时加载的库" tabindex="-1">程序在运行时加载的库 <a class="header-anchor" href="#程序在运行时加载的库" aria-label="Permalink to &quot;程序在运行时加载的库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标平台</th><th>运行时从系统加载</th><th>静态链接</th></tr></thead><tbody><tr><td>Linux（glibc）</td><td>glibc 2.17 及以上：<code>libc</code>、<code>libm</code>、<code>libpthread</code>、<code>libdl</code>、<code>librt</code> 与动态加载器</td><td><code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code>、<code>compiler-rt</code> builtins</td></tr><tr><td>Linux（musl）</td><td>无：仅发起 Linux 内核系统调用</td><td><code>musl</code>、<code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code>、<code>compiler-rt</code> builtins</td></tr><tr><td>macOS</td><td><code>libSystem</code>（含 C 标准库与栈展开库）及程序所链接的系统 framework</td><td><code>libc++</code>、<code>libc++abi</code>、<code>compiler-rt</code> builtins</td></tr><tr><td>Windows（MinGW）</td><td>Windows 10 及更高版本自带的系统 DLL（<code>kernel32.dll</code> 等）与 UCRT（<code>api-ms-win-crt-*</code>）</td><td><code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code>、<code>compiler-rt</code> builtins、<code>winpthreads</code>、<code>mingw-w64</code> 运行时</td></tr><tr><td>Windows（MSVC）</td><td>与 MinGW 相同，加载 Windows 系统 DLL 与 UCRT（<code>ucrtbase.dll</code>）</td><td><code>libc++</code>（或微软的 STL）、微软的 VC 运行时（<a href="./windows#the-hybrid-crt">混合 CRT</a>）、<code>compiler-rt</code> builtins</td></tr></tbody></table><p>中间一列的库无法静态链接进程序，也不能随程序分发：glibc 的动态加载器与 <code>libc</code> 共同构成宿主机系统的底层 ABI，<code>libSystem</code> 是 macOS 内核唯一受支持的调用接口，而 UCRT 与系统 DLL 则是 Windows 10 及更高版本的操作系统组件。最右一列的所有库均可链接进二进制文件，xclang 默认将它们全部静态链接。</p><p>工具链自身的可执行程序也遵循同一规则：在包括 macOS 在内的所有主机上，<code>clang</code>、<code>lld</code>、LLVM 二进制工具与 <code>xclang</code> 均静态链接 xclang 自身的 <code>libc++</code>，不会加载 <code>/usr/lib/libc++.1.dylib</code>。</p><p>唯一的例外是仅供测试使用的动态 sanitizer 运行时库（<a href="./../features/sanitizers">sanitizer</a>）。在 macOS 上，sanitizer 运行时库是从工具链或可执行文件所在目录加载的 <code>.dylib</code> 文件（<a href="./macos#the-sanitizers-dylibs">sanitizer 的 dylib</a>）；在 <code>x86_64</code> Windows（MinGW 与 MSVC）上，AddressSanitizer 运行时库是从可执行文件所在目录或 <code>PATH</code> 加载的 DLL（<a href="./windows#asan-s-dll">ASan 的 DLL</a>）。启用 sanitizer 的构建用于测试，而非对外发布。</p><h2 id="为什么不使用共享运行时库" tabindex="-1">为什么不使用共享运行时库 <a class="header-anchor" href="#为什么不使用共享运行时库" aria-label="Permalink to &quot;为什么不使用共享运行时库&quot;">​</a></h2><p>大多数工具链默认动态链接共享的 <code>libc++</code> 或 <code>libstdc++</code>，这会把三项成本转嫁到程序部署阶段：</p><ul><li><strong>目标机器必须安装对应的运行时库。</strong> 在 Linux 上，操作系统默认不预装 <code>libc++.so.1</code>，动态链接它的程序必须额外安装系统软件包、通过 <code>DT_RUNPATH</code> 随附库文件副本，或运行在容器中。在 Windows 上，每个可执行文件旁都必须随附 <code>libc++.dll</code>、<code>libunwind.dll</code> 与 <code>libwinpthread-1.dll</code>（或 <code>vcruntime140.dll</code> 与 <code>msvcp140.dll</code>）。</li><li><strong>实际运行的库版本取决于目标机器，而非构建环境。</strong> 从操作系统加载的共享库版本取决于目标机器上安装了什么版本，未必是编译和测试程序时使用的版本。在 macOS 上，动态链接 <code>/usr/lib/libc++.1.dylib</code> 还会使可用的 C++ 标准库特性受限于目标系统的 macOS 版本，而非取决于工具链版本（<a href="./macos#why-xclang-s-libc-and-not-the-system-s">macOS</a>）。</li><li><strong>构建环境会渗透到产物中。</strong> conda-forge 的编译器会链接 <code>libcxx</code> 与 <code>libstdcxx</code> conda 软件包，并通过 <code>run_exports</code> 将它们记录为产物的运行时依赖。在安装了这些包的 conda 环境内，程序可以正常运行；但一旦脱离 conda 环境，编译出的二进制文件就会因缺少共享库而无法在用户机器上运行。由于 xclang 将运行时库静态链接进每个二进制文件且不使用 <code>run_exports</code>，它不用于构建 conda-forge 软件包（<a href="./roadmap#conda-forge">路线图</a>）。</li></ul><p>静态链接运行时库的代价是二进制文件体积增大（每个可执行文件都包含自身用到的那部分 <code>libc++</code> 代码），以及每个共享库内部各自持有一份独立的 <code>libc++</code>。</p><h2 id="每个共享库各自持有一份-libc" tabindex="-1">每个共享库各自持有一份 libc++ <a class="header-anchor" href="#每个共享库各自持有一份-libc" aria-label="Permalink to &quot;每个共享库各自持有一份 libc++&quot;">​</a></h2><p><code>libc++</code>、<code>libc++abi</code> 与 <code>libunwind</code> 均构建为具有隐藏符号可见性（<code>LIBCXX_HERMETIC_STATIC_LIBRARY=ON</code>、<code>LIBCXXABI_HERMETIC_STATIC_LIBRARY=ON</code>、<code>LIBUNWIND_HIDE_SYMBOLS=ON</code>）的位置无关静态库（<code>CMAKE_POSITION_INDEPENDENT_CODE=ON</code>）。由 xclang 链接的每个可执行文件和每个共享库（<code>-shared</code>）都包含各自私有的一份 <code>libc++</code>，不会向其他共享库导出任何符号（<a href="./roadmap#shared-runtime">路线图中的共享运行时库说明</a>）。</p><p>当应用程序加载多个以这种方式链接的共享库时，需要注意与 <a href="https://developer.android.com/ndk/guides/cpp-support" target="_blank" rel="noreferrer">Android NDK 文档</a>中静态 <code>libc++</code> 相同的限制：</p><ul><li><strong>C++ 对象与内存分配不得跨越共享库边界。</strong> 在一个共享库中构造 <code>std::string</code> 或 <code>std::vector</code>，再到另一个共享库中析构或扩容，会混用两份运行时库实例的状态。在某个共享库中分配的内存必须在同一个共享库中释放。</li><li><strong>跨共享库的异常与 RTTI。</strong> 每份运行时库各自拥有一套 <code>std::exception</code> 及其他标准类型的 <code>std::type_info</code> 实例。在 Linux 与 macOS 上，<code>libc++</code> 按地址比较 <code>type_info</code>，因此一个共享库抛出的标准异常在另一个共享库中只能被 <code>catch (...)</code> 捕获，而无法被 <code>catch (const std::exception&amp;)</code> 捕获。如果在所有平台上都改为按名称字符串比较 <code>type_info</code>，不仅每次类型不匹配时都要付出字符串比较开销，还会把不同匿名命名空间中的同名类型误判为同一类型，因此 xclang 保留了上游 <code>libc++</code> 的默认行为。在 Windows 上，<code>type_info</code> 按名称比较，只要调用双方使用同一种 ABI，即可跨 DLL 正常捕获异常。</li><li><strong><code>libc++</code> 的全局状态按共享库隔离</strong>：包括 <code>std::cout</code> 的缓冲区、<code>std::locale::global</code>、<code>std::set_new_handler</code> 与 <code>std::set_terminate</code>。</li></ul><p>将所有 C++ 库静态链接进单个可执行文件的程序不会遇到这些问题，这也是 <a href="./bazel-module#static-by-default">Bazel 模块默认静态链接依赖库</a>的原因。跨越共享库或插件边界时，请暴露 C 接口。</p><h2 id="为什么选择-glibc-2-17" tabindex="-1">为什么选择 glibc 2.17 <a class="header-anchor" href="#为什么选择-glibc-2-17" aria-label="Permalink to &quot;为什么选择 glibc 2.17&quot;">​</a></h2><p>glibc 对符号做了版本管理，链接器会将每个符号绑定到构建时 sysroot 的 <code>libc.so.6</code> 中存在的最高版本。因此，Linux 二进制文件只能在链接时所用版本或更高版本的 glibc 上运行，无法在更早的 glibc 版本上运行。</p><p>xclang 的 Linux sysroot 包含 glibc 2.17 的头文件、启动目标文件与桩库（通过 conda-forge 的 <code>sysroot_linux-64</code> 与 <code>sysroot_linux-aarch64</code> 2.17 软件包取自 CentOS 7），与 conda-forge 以及 <a href="https://github.com/rust-lang/rust/blob/main/src/ci/docker/host-x86_64/dist-x86_64-linux/Dockerfile" target="_blank" rel="noreferrer">Rust 官方 Linux 目标平台</a>采用的最低基线一致。glibc 2.17 缺失的特性（<code>-static-pie</code>、PIE 下的 <code>-pg</code> 以及 <code>quadmath.h</code>）见<a href="./../guide/cross-compiling#glibc-2-17-floor-static-pie-and-pg">交叉编译</a>，更高版本的 glibc 目标平台目前在<a href="./roadmap#glibc-newer">考虑中</a>。由于 glibc 2.17 早于 glibc 2.18 引入的 <code>__cxa_thread_atexit_impl</code>，<code>libc++abi</code> 使用 <code>LIBCXXABI_HAS_CXA_THREAD_ATEXIT_IMPL=OFF</code> 构建，以弱符号形式引用这个函数，并在 glibc 2.17 上回退使用自带的 <code>thread_local</code> 析构函数列表。</p><p><code>toolchain/sysroot.ts</code> 对 glibc 2.17 sysroot 做了两项调整，使其适用于所有主机和链接模式：</p><ul><li><strong><code>-static</code> 链接。</strong> glibc 2.17 的 <code>libpthread.a</code> 是单个目标文件，重定义了 <code>libc.a</code> 中的 <code>__libc_sigaction</code> 与取消点（cancellation point）。由于 <code>libunwind</code> 的依赖库记录会在 <code>libc.a</code> 之后引入 <code>libpthread.a</code>，导致 <code>-static</code> 链接因重复符号报错失败。为此，sysroot 将 <code>libc.a</code> 重命名为 <code>libglibc.a</code>，并把 <code>libc.a</code> 替换为链接器脚本 <code>GROUP ( /usr/lib64/libpthread.a /usr/lib64/libglibc.a )</code>，使两个静态库按正确的顺序一并搜索并顺利完成链接。</li><li><strong>无符号链接与大小写冲突。</strong> 在 Windows 上创建符号链接需要管理员权限或开启开发者模式，且 Windows 的 conda 软件包不支持符号链接。因此在 Linux sysroot 中，目录符号链接（<code>lib -&gt; lib64</code>）直接在链接器脚本内展开并移除，soname 链接（<code>libc.so.6 -&gt; libc-2.17.so</code>）直接替换为目标文件本身，开发期 <code>.so</code> 链接（如 <code>libm.so</code>）则改写为与 glibc 自身的 <code>libc.so</code> 类似的 <code>INPUT ( ... )</code> 链接器脚本。对于文件名仅大小写不同的 netfilter 头文件（如并存的 <code>xt_DSCP.h</code> 与 <code>xt_dscp.h</code>），只保留全小写文件，确保所有压缩包都能在不区分大小写的文件系统上正常解压。</li></ul><h2 id="gcc-库名兼容" tabindex="-1">GCC 库名兼容 <a class="header-anchor" href="#gcc-库名兼容" aria-label="Permalink to &quot;GCC 库名兼容&quot;">​</a></h2><p>面向 GCC 编写的构建脚本常在链接命令行中直接指定 GCC 的运行时库：宽原子操作使用 <code>-latomic</code>，栈展开库使用 <code>-lgcc_s</code> 与 <code>-lgcc_eh</code>，编译器内置函数使用 <code>-lgcc</code>，MinGW 上的栈保护使用 <code>-lssp</code>。在 xclang 中，这些函数分别由 <code>compiler-rt</code>、<code>libunwind</code> 与 <code>mingw-w64</code> 提供。为此，Linux、musl 与 MinGW 的 sysroot 均以这些名称提供了空静态库桩文件（<code>!&lt;arch&gt;\\n</code>），使面向 GCC 的链接命令无需修改即可通过：</p><ul><li><strong><code>-latomic</code></strong>：针对宽度超出无锁原子操作范围的类型（如结构体，或未启用 <code>cx16</code> 时的 <code>__int128</code>），其 <code>__atomic_*</code> 函数已直接编译进 <code>compiler-rt</code> builtins 中（<code>COMPILER_RT_EXCLUDE_ATOMIC_BUILTIN=OFF</code>）。</li><li><strong><code>-lgcc</code>, <code>-lgcc_s</code>, <code>-lgcc_eh</code></strong>：编译器辅助函数与栈展开分别由 <code>compiler-rt</code> 和 <code>libunwind</code> 提供。由于 <code>libgcc_s.a</code> 与 <code>libgcc_eh.a</code> 是空静态库，像 <code>rustc</code> 编译 <code>*-unknown-linux-gnu</code> 那样传入 <code>-nodefaultlibs</code> 链接时，若不额外传入 <code>-l:libunwind.a</code> 就不会链接栈展开库；<code>xclang cargo</code> 会自动处理这一替换（<a href="./../integrations/cargo#what-xclang-cargo-sets">Rust 与 Cargo</a>，将 <code>libgcc_s.a</code> 改为链接器脚本目前在<a href="./roadmap#libgcc-s-script">考虑中</a>）。</li><li><strong><code>-lssp</code>, <code>-lssp_nonshared</code></strong>：启用 <code>-fstack-protector</code> 时，<code>clang</code> 的 MinGW 驱动会自动添加这两个库，其函数实际由 <code>mingw-w64</code> 中的 <code>libmingwex.a</code> 提供。</li><li><strong><code>-lstdc++</code></strong>：无需提供桩库，因为除非传入了 <code>-nostdlib</code>、<code>-nodefaultlibs</code> 或 <code>-nostdlib++</code>，否则 <code>clang</code> 驱动会自动将 <code>-lstdc++</code> 替换为 <code>-lc++</code>。</li><li><strong><code>windres</code></strong>：在 <code>bin/</code> 下链接到 <code>llvm-windres</code>，这是 CMake 的 MinGW 平台模块在编译 <code>.rc</code> 资源文件时查找的工具名。</li></ul><h2 id="使用-musl-构建静态程序" tabindex="-1">使用 musl 构建静态程序 <a class="header-anchor" href="#使用-musl-构建静态程序" aria-label="Permalink to &quot;使用 musl 构建静态程序&quot;">​</a></h2><p>与 glibc 不同，musl 从设计上就支持静态链接。<code>x86_64-unknown-linux-musl</code> 与 <code>aarch64-unknown-linux-musl</code> 目标平台会将 musl 1.2.6（使用 <code>--disable-shared</code> 并开启异步栈展开表编译）、<code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code> 与 <code>compiler-rt</code> 一并静态链接为不含程序解释器（<code>PT_INTERP</code>）和动态段的静态可执行文件，连 C 标准库也不再作为运行时外部依赖。</p><p>静态 musl 二进制文件的取舍如下：</p><ul><li><strong>二进制文件体积</strong>：在 Linux x64 上，编译一个使用 <code>iostream</code> 的 C++ hello-world 程序时，静态链接 musl 在剥离符号前仅增加 51 KB（1.17 MB 对比 1.12 MB），剥离符号后仅增加 27 KB（826 KB 对比 799 KB）。</li><li><strong>不支持共享库与动态 sanitizer</strong>：内置 sysroot 不含 <code>libc.so</code>，因此不支持调用 <code>dlopen</code> 或构建 <code>-shared</code> 共享库，且可用的 sanitizer 只有 UBSan（<a href="./../features/sanitizers#musl-targets">sanitizer</a>）。</li><li><strong>与 glibc 的运行时行为差异</strong>：多线程下的内存分配器锁争用、固定按 <code>C</code> locale 格式化，以及不经由 NSS 直接发起 DNS 查询等差异见<a href="./../guide/cross-compiling#musl-targets">交叉编译</a>。</li></ul><h2 id="平台的-c-标准库" tabindex="-1">平台的 C++ 标准库 <a class="header-anchor" href="#平台的-c-标准库" aria-label="Permalink to &quot;平台的 C++ 标准库&quot;">​</a></h2><p>如果程序需要跨接口向使用平台的 C++ 标准库构建的库（例如 Linux 发行版的 <code>libstdc++</code> 软件包、使用 <code>/usr/lib/libc++.1.dylib</code> 的 macOS 库，或使用 MSVC STL 编译的 Windows 库）传递 C++ 标准库类型，就必须使用相同的 C++ 标准库与 ABI。传入 <code>-stdlib=platform</code> 会切换到 <code>bin/&lt;triple&gt;-system.cfg</code>，主动退出封闭性规则（<a href="./toolchain#the-platform-s-c-library">工具链结构</a>）；具体用法以及生成的二进制文件在各目标平台上运行时加载的库见<a href="./../guide/cross-compiling#the-platform-s-c-library">交叉编译</a>。</p>',34)])])}const p=c(t,[["render",l]]);export{h as __pageData,p as default};
